let _markdown = "\n\n<FeedbackBlock id=\"967a202a22181007\" body=\"Fumadocs MDX provides MDX presets to simplify configurations of features like syntax highlighting.\">\n  Fumadocs MDX provides MDX presets to simplify configurations of features like **syntax highlighting**.\n</FeedbackBlock>\n\nDefault Preset [#default-preset]\n\n<FeedbackBlock id=\"5cde1282357f8efc\" body=\"A preset designed for documentation sites, it is enabled by default for global MDX options.\">\n  A preset designed for documentation sites, it is enabled by default for global MDX options.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"6c0e1ed2c7fcb5e4\" body=\"To override the defaults, it accepts an interface inherited from ProcessorOptions:\">\n  To override the defaults, it accepts an interface inherited from [`ProcessorOptions`](https://mdxjs.com/packages/mdx/#processoroptions):\n</FeedbackBlock>\n\nRemark Plugins [#remark-plugins]\n\n<FeedbackBlock id=\"7e8c21ffa80d641f\" body=\"These plugins are applied by default:\">\n  These plugins are applied by default:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"93c58ab1eabe50ee\" body=\"Remark Image - Handle images.Remark Heading - Extract table of contents.Remark Structure - Generate search indexes.\">\n  * [Remark Image](/docs/headless/mdx/remark-image) - Handle images.\n  * [Remark Heading](/docs/headless/mdx/headings) - Extract table of contents.\n  * [Remark Structure](/docs/headless/mdx/structure) - Generate search indexes.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"394c832170be8c58\" body=\"Add other remark plugins with:\">\n  Add other remark plugins with:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Global Config\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Global Config\">\n      Global Config\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Collection Config\">\n      Collection Config\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Global Config\">\n    ```ts\n    import { defineConfig } from 'fumadocs-mdx/config';\n    import { myPlugin } from './remark-plugin';\n\n    export default defineConfig({\n      mdxOptions: {\n        remarkPlugins: [myPlugin],\n        // You can also pass a function to control the order of remark plugins.\n        remarkPlugins: (v) => [myPlugin, ...v],\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Collection Config\">\n    ```ts\n    import { defineCollections, applyMdxPreset } from 'fumadocs-mdx/config';\n    import { myPlugin } from './remark-plugin';\n\n    export const blog = defineCollections({\n      type: 'doc',\n      mdxOptions: applyMdxPreset({\n        remarkPlugins: [myPlugin],\n        // You can also pass a function to control the order of remark plugins.\n        remarkPlugins: (v) => [myPlugin, ...v],\n      }),\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nRehype Plugins [#rehype-plugins]\n\n<FeedbackBlock id=\"7e8c21ffa80d641f-1\" body=\"These plugins are applied by default:\">\n  These plugins are applied by default:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"7ceb3b67040453f2\" body=\"Rehype Code - Syntax highlighting.Rehype TOC - Export table of contents.\">\n  * [Rehype Code](/docs/headless/mdx/rehype-code) - Syntax highlighting.\n  * [Rehype TOC](/docs/headless/mdx/headings#rehype-toc) - Export table of contents.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"eca22dff36e5f650\" body=\"Same as remark plugins, you can pass an array or a function to add other rehype plugins.\">\n  Same as remark plugins, you can pass an array or a function to add other rehype plugins.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Global Config\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Global Config\">\n      Global Config\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Collection Config\">\n      Collection Config\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Global Config\">\n    ```ts\n    import { defineConfig } from 'fumadocs-mdx/config';\n    import { myPlugin } from './rehype-plugin';\n\n    export default defineConfig({\n      mdxOptions: {\n        rehypePlugins: (v) => [myPlugin, ...v],\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Collection Config\">\n    ```ts\n    import { defineCollections, applyMdxPreset } from 'fumadocs-mdx/config';\n    import { myPlugin } from './rehype-plugin';\n\n    export const blog = defineCollections({\n      type: 'doc',\n      mdxOptions: applyMdxPreset({\n        rehypePlugins: (v) => [myPlugin, ...v],\n      }),\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nCustomise Built-in Plugins [#customise-built-in-plugins]\n\n<FeedbackBlock id=\"56236422ee4bb508\" body=\"Customise the options of built-in plugins like:\">\n  Customise the options of built-in plugins like:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Global Config\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Global Config\">\n      Global Config\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Collection Config\">\n      Collection Config\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Global Config\">\n    ```ts\n    import { defineConfig } from 'fumadocs-mdx/config';\n\n    export default defineConfig({\n      mdxOptions: {\n        rehypeCodeOptions: {\n          // options\n        },\n        remarkImageOptions: {\n          // options\n        },\n        remarkHeadingOptions: {\n          // options\n        },\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Collection Config\">\n    ```ts\n    import { defineCollections, applyMdxPreset } from 'fumadocs-mdx/config';\n\n    export const blog = defineCollections({\n      type: 'doc',\n      mdxOptions: applyMdxPreset({\n        rehypeCodeOptions: {\n          // options\n        },\n        remarkImageOptions: {\n          // options\n        },\n        remarkHeadingOptions: {\n          // options\n        },\n      }),\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n";
